// Detecta meetings asociadas al contacto de HubSpot y las clasifica:
//   - 'booked'       → meeting creada DESPUÉS del sent_at (atribuible al outbound)
//   - 'booked_other' → meeting creada ANTES o ya existente pre-outbound
//                      (la persona ya tenía contacto/reunión por otro canal)
//
// Cada item de salida representa UN outcome a insertar. La meeting representativa
// del bucket es la PRÓXIMA FUTURA (start_time > now, mínimo); si no hay futura,
// la más reciente por start_time. Esto permite saber rápido "tiene meeting próxima
// agendada" sin parsear histórico.

const items = $input.all();
const out = [];
const NOW = Date.now();

function pickRepresentative(bucket) {
  // 1. Si hay future (start_time > now): la próxima en el calendario
  const future = bucket
    .filter(m => {
      const t = m.properties?.hs_meeting_start_time ? Date.parse(m.properties.hs_meeting_start_time) : 0;
      return t > NOW;
    })
    .sort((a, b) => {
      const ta = Date.parse(a.properties.hs_meeting_start_time);
      const tb = Date.parse(b.properties.hs_meeting_start_time);
      return ta - tb; // ascending → la más próxima primero
    });
  if (future.length > 0) return future[0];
  // 2. Sin futuras: la más reciente por start_time (puede ser pasada)
  const sorted = bucket.slice().sort((a, b) => {
    const ta = a.properties?.hs_meeting_start_time ? Date.parse(a.properties.hs_meeting_start_time) : 0;
    const tb = b.properties?.hs_meeting_start_time ? Date.parse(b.properties.hs_meeting_start_time) : 0;
    return tb - ta;
  });
  return sorted[0];
}

function buildOutcome(row, m, outcomeType, bucketSize, reason) {
  return { json: {
    pipeline_id: row.id,
    outcome: outcomeType,
    outcome_source: 'hubspot_sync',
    occurred_at: m.properties?.hs_meeting_start_time || m.properties?.hs_createdate || new Date().toISOString(),
    meeting_start_time: m.properties?.hs_meeting_start_time || null,
    details: {
      meeting_id: m.id,
      meeting_title: m.properties?.hs_meeting_title,
      meeting_start_time: m.properties?.hs_meeting_start_time,
      meeting_outcome: m.properties?.hs_meeting_outcome,
      meeting_createdate: m.properties?.hs_createdate,
      meetings_total_in_bucket: bucketSize,
      reason,
    }
  }};
}

for (const item of items) {
  const row = item.json;
  const hsId = row.hubspot_contact_id;
  const sentAt = row.sent_at ? Date.parse(row.sent_at) : 0;
  if (!hsId || !sentAt) continue;

  try {
    const meetings = await this.helpers.httpRequestWithAuthentication.call(
      this, 'hubspotAppToken',
      {
        method: 'GET',
        url: 'https://api.hubapi.com/crm/v3/objects/contacts/' + encodeURIComponent(hsId) + '/associations/meetings',
        json: true,
      }
    );
    const meetingIds = (meetings.results || []).map(r => r.id).slice(0, 20);
    if (meetingIds.length === 0) continue;

    const batch = await this.helpers.httpRequestWithAuthentication.call(
      this, 'hubspotAppToken',
      {
        method: 'POST',
        url: 'https://api.hubapi.com/crm/v3/objects/meetings/batch/read',
        body: {
          properties: ['hs_meeting_title', 'hs_meeting_start_time', 'hs_meeting_outcome', 'hs_createdate'],
          inputs: meetingIds.map(id => ({ id })),
        },
        json: true,
      }
    );

    const all = (batch.results || []);
    const postSent = [];
    const preSent = [];
    for (const m of all) {
      const created = m.properties?.hs_createdate ? Date.parse(m.properties.hs_createdate) : 0;
      if (!created) continue;
      if (created > sentAt) postSent.push(m);
      else preSent.push(m);
    }

    if (postSent.length > 0) {
      const m = pickRepresentative(postSent);
      out.push(buildOutcome(row, m, 'booked', postSent.length, 'meeting_created_after_outbound_sent'));
    }
    if (preSent.length > 0) {
      const m = pickRepresentative(preSent);
      out.push(buildOutcome(row, m, 'booked_other', preSent.length, 'meeting_existed_before_outbound_sent'));
    }
  } catch (e) {
    // fail-open: si HubSpot falla, esta vuelta no marca
  }
}

return out;

// Dedup por (pipeline_id, outcome). Items con la misma tupla ya en la tabla
// se descartan. Fail-closed: si el dedup falla, no insertamos para evitar duplicados.
const items = $input.all();
if (items.length === 0) return [];

const ids = items.map(i => i.json.pipeline_id);
const url = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_outcomes';
const params = new URLSearchParams({
  select: 'pipeline_id,outcome',
  pipeline_id: 'in.(' + ids.map(id => '"' + id + '"').join(',') + ')',
  outcome: 'in.(booked,booked_other)',
});

let existing = new Set();
try {
  const resp = await this.helpers.httpRequestWithAuthentication.call(
    this, 'supabaseApi',
    { method: 'GET', url: url + '?' + params.toString(), json: true }
  );
  (Array.isArray(resp) ? resp : []).forEach(r => existing.add(r.pipeline_id + '|' + r.outcome));
} catch (e) {
  return [];
}

return items.filter(i => !existing.has(i.json.pipeline_id + '|' + i.json.outcome));
